import{_ as o,o as a,c,a3 as d}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"The Bazel Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"The Bazel Module | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/bazel-module"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/bazel-module"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/bazel-module"}]]},"headers":[],"relativePath":"xclang/design/bazel-module.md","filePath":"en/xclang/design/bazel-module.md","lastUpdated":1794509097000}'),t={name:"xclang/design/bazel-module.md"};function i(n,e,s,l,r,h){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="the-bazel-module" tabindex="-1">The Bazel Module <a class="header-anchor" href="#the-bazel-module" aria-label="Permalink to &quot;The Bazel Module&quot;">​</a></h1><p>xclang&#39;s Bazel module (<code>packages/bazel</code>) makes C++ builds hermetic and cacheable across checkouts and machines: every toolchain and SDK file an action reads is a declared Bazel input, no command line or build output contains an absolute path (except for Xcode&#39;s SDK and native sanitizer rpaths on macOS hosts), and <code>cc_library</code> dependencies link statically into programs and tests by default. How to set up and use the module is in <a href="./../integrations/bazel">Bazel</a>, and its labels, flags and features are in the <a href="./../reference/bazel-api">Bazel API</a>.</p><h2 id="every-toolchain-file-is-an-input" tabindex="-1">Every Toolchain File Is an Input <a class="header-anchor" href="#every-toolchain-file-is-an-input" aria-label="Permalink to &quot;Every Toolchain File Is an Input&quot;">​</a></h2><p>The <code>xclang_toolchain</code> repository rule downloads the host toolchain archive by its pinned <code>sha256</code> from <code>bazel/versions.bzl</code>. Every file of the archive that a compile or link action reads is declared in its <code>cc_toolchain</code> filegroups: the binaries in <code>bin/</code>, <code>clang</code>&#39;s resource headers, the target&#39;s sysroot headers and shared <code>libc++</code> / <code>mingw-w64</code> headers for compiling, and the target&#39;s sysroot libraries and <code>compiler-rt</code> for linking. Vendor SDKs fetched by the module extension are declared inputs in the same way (<a href="#vendor-sdks-as-repositories">below</a>); the only host path outside Bazel is Xcode&#39;s macOS SDK on macOS hosts, located by <code>xcrun --show-sdk-path</code>.</p><p>Before the module existed, xclang&#39;s Bazel setup wrapped a <code>clang</code> found on <code>PATH</code> with no declared toolchain files, which broke caching in two ways:</p><ul><li>Any change to <code>PATH</code> invalidated the toolchain repository and rebuilt the workspace.</li><li>Upgrading <code>clang</code> on <code>PATH</code> changed no action input, so the build cache continued serving object files from the previous compiler.</li></ul><p>Declaring every toolchain file as an action input fixes both: upgrading the <code>xclang</code> module changes the input digests of every compile and link action and triggers a rebuild, while building with the same release in another directory or on another machine shares cache hits.</p><p>The trade-off is sandbox staging: Bazel&#39;s sandbox creates links for thousands of declared toolchain files on every compile and link action. On Windows hosts, Bazel runs actions without a sandbox by default (unless <code>--experimental_use_windows_sandbox</code> is enabled), so missing input declarations are caught by Linux and macOS builds of the same targets instead; and because Bazel&#39;s default output root on Windows exceeds path length limits when staging deep toolchain and SDK trees, Windows hosts set <code>startup --output_user_root=C:/b</code> (<a href="./../integrations/bazel#on-a-windows-host">on a Windows host</a>).</p><h2 id="no-absolute-paths" tabindex="-1">No Absolute Paths <a class="header-anchor" href="#no-absolute-paths" aria-label="Permalink to &quot;No Absolute Paths&quot;">​</a></h2><p>A disk or remote cache can reuse an action across directories and machines only when both the action command line and the action outputs contain no checkout-, output-base- or sandbox-specific paths. <code>packages/bazel</code> removes absolute paths from every compile, module and link action:</p><ul><li><strong>Rewritten config files</strong>: <code>clang</code> resolves <code>&lt;CFGDIR&gt;</code> in a config file to an absolute path, which then enters <code>.d</code> dependency files. During repository setup, <code>_bazel_cfg</code> (<code>bazel/repositories.bzl</code>) writes copies of each target&#39;s config files into <code>cfg/</code> with <code>&lt;CFGDIR&gt;/..</code> replaced by <code>external/&lt;repository&gt;</code> and <code>-resource-dir=external/&lt;repository&gt;/lib/clang/&lt;major&gt;</code>, and the toolchain passes <code>--no-default-config --config=external/&lt;repository&gt;/cfg/&lt;target&gt;.cfg</code>.</li><li><strong>Relative tool prefixes</strong>: <code>-no-canonical-prefixes</code> in compile and link flags, and wrapper scripts (<code>scan_deps</code> and <code>dsym_link</code>) that locate tools relative to their own directory.</li><li><strong>Debug information and binary timestamps</strong>: <code>-ffile-compilation-dir=.</code> on every compile; <code>-Wl,-oso_prefix,.</code> on macOS links; <code>-Wl,--no-insert-timestamp</code> on MinGW links; and on MSVC targets <code>-mno-incremental-linker-compatible</code> and <code>-gno-codeview-command-line</code> on compiles (keeping Windows launcher paths out of CodeView records), <code>-Wl,/Brepro</code> on links, <code>/pdbsourcepath:.</code> for PDB source paths, and PDB names embedded without a directory prefix (<a href="./../features/debugging#paths-in-debug-information">paths in debug information</a>).</li><li><strong>C++20 module files</strong>: <code>-Xclang -fmodule-file-home-is-cwd</code> so <code>.pcm</code> files record input paths relative to the execution root, and <code>-Xclang -fmodules-embed-all-files</code> (<code>modules_embed_all_files</code>, on by default) so importers compiled with <code>-g</code> read source text from the <code>.pcm</code> itself inside the sandbox (<a href="./../features/modules#build-caches-and-modules">build caches and modules</a>).</li><li><strong>Preprocessor timestamps</strong>: <code>-Wno-builtin-macro-redefined</code> with <code>__DATE__</code>, <code>__TIME__</code> and <code>__TIMESTAMP__</code> defined to <code>&quot;redacted&quot;</code>.</li></ul><p>Two absolute paths remain on macOS hosts: Xcode&#39;s SDK path (<code>-isysroot</code>), which comes from the host machine, and <code>-Wl,-rpath,&lt;absolute_root&gt;/lib/clang/&lt;major&gt;/lib/darwin</code> when a sanitizer feature is enabled for a native macOS build so the binary finds the sanitizer <code>.dylib</code> at run time.</p><h2 id="a-toolchain-per-host-and-target" tabindex="-1">A Toolchain per Host and Target <a class="header-anchor" href="#a-toolchain-per-host-and-target" aria-label="Permalink to &quot;A Toolchain per Host and Target&quot;">​</a></h2><p>Because every host archive contains the sysroots and runtimes for all bundled targets, the module registers a <code>cc_toolchain</code> for every <code>(host, target)</code> pair: <code>exec_compatible_with</code> the host OS and CPU, and <code>target_compatible_with</code> the target platform. Bazel selects the toolchain matching the host machine and the <code>--platforms</code> target, and downloads only that host&#39;s toolchain archive.</p><p>For targets that require a vendor SDK (the MSVC targets, and the macOS targets on Linux and Windows hosts), a build without the corresponding tag in the root <code>MODULE.bazel</code> resolves to a toolchain that fails immediately at analysis time and prints the required <code>xclang.windows_sdk</code> or <code>xclang.macos_sdk</code> tag.</p><p>The platforms in <code>@xclang//platforms:&lt;target&gt;</code> declare <code>@platforms//os</code>, <code>@platforms//cpu</code> and a C library constraint (<code>@xclang//platforms/libc:glibc</code>, <code>:musl</code>, <code>:mingw</code>, <code>:macosx</code> or <code>:msvc</code>). Because the musl toolchains (<code>//bazel/toolchains/musl:all</code>) and MSVC toolchains (<code>//bazel/toolchains/msvc:all</code>) require <code>:musl</code> or <code>:msvc</code> and are registered in <code>MODULE.bazel</code> ahead of <code>//bazel/toolchains:all</code> (which match on OS and CPU alone), a custom <code>platform</code> without a <code>libc</code> constraint defaults to <code>glibc</code> on Linux and MinGW on Windows.</p><h2 id="rules-cc-s-config-copied" tabindex="-1">rules_cc&#39;s Config, Copied <a class="header-anchor" href="#rules-cc-s-config-copied" aria-label="Permalink to &quot;rules_cc&#39;s Config, Copied&quot;">​</a></h2><p>Changing a <code>.bzl</code> file in another Bazel module through <code>single_version_override</code> patches only works when placed in the root <code>MODULE.bazel</code>, which would require every project using <code>xclang</code> to carry patch files in its own repository; and patching the build&#39;s <code>rules_cc</code> repository in place breaks whenever a new <code>rules_cc</code> version edits nearby lines (as <code>rules_cc</code> 0.2.28 did). Migrating to <code>rules_cc</code>&#39;s rule-based toolchain API would have required reimplementing <code>--macos_minimum_os</code>, <code>libtool</code>, dead stripping and sanitizer features.</p><p><code>packages/bazel/bazel/unix_cc_toolchain_config.bzl</code> therefore carries xclang&#39;s own copy of <code>rules_cc</code> 0.2.28&#39;s <code>unix_cc_toolchain_config.bzl</code>. Because the copy loads only public files from <code>rules_cc</code>, <code>apple_support</code> and <code>bazel_skylib</code>, it works with any <code>rules_cc</code> 0.2.25 or later without a consumer override.</p><p>Compared to upstream <code>rules_cc</code>, xclang&#39;s config and <code>bazel/toolchain.bzl</code> add:</p><ul><li><code>.exe</code> and <code>.dll</code> output names for MinGW and MSVC targets, and no <code>rpath</code> on Windows;</li><li>MSVC target support using the GNU-style <code>clang</code> driver with <code>lld-link</code> flags, <code>-std=c++17</code> by default, no PIC, PDB generation (<code>generate_pdb_file</code>), CRT selection (<code>dynamic_link_msvcrt</code>, <code>debug_msvcrt</code>), and runtime DLL staging (<code>copy_dynamic_libraries_to_binary</code>);</li><li>static linking of <code>cc_library</code> dependencies by default (<a href="#static-by-default">below</a>);</li><li>external repositories&#39; headers passed via <code>-isystem</code> (<code>external_include_paths</code> on by default) so dependency warnings do not fail the build;</li><li>sanitizer flags, switching to the prebuilt ASan <code>libc++</code> under <code>asan</code>, building <code>libc++</code>, <code>libc++abi</code> and <code>libunwind</code> from <code>libc++/src</code> under <code>--@xclang//runtimes:source</code>, and supporting MemorySanitizer (<code>msan</code>) on the glibc Linux targets (<a href="./../features/runtimes-from-source">runtimes from source</a>);</li><li><code>gc_sections</code> enabled in <code>opt</code> on Linux and disabled by default on Windows (<a href="./windows#gc-sections-and-static-initializers"><code>gc-sections</code> and static initializers</a>);</li><li>macOS links without <code>-fobjc-link-runtime</code> unless <code>macos_default_link_flags</code> is enabled, <code>--macos_minimum_os</code> clamped to at least <code>13.0</code>, library objects passed between <code>--start-lib</code> and <code>--end-lib</code> on Linux and macOS (so <code>dsymutil</code> never confuses same-named archive members with zeroed Bazel timestamps), and <code>dsym_link</code> generating the <code>.dSYM</code> bundle during the link with <code>dsymutil --linker classic</code> (avoiding DWARF 5 line tables from LLVM 23&#39;s parallel linker that crash <code>atos</code>; <a href="./../features/debugging#why-a-dsym-comes-from-the-link">why a dSYM comes from the link</a>);</li><li>format-specific binary stripping (<code>--strip-unneeded</code> for ELF and COFF, <code>--strip-all</code> with <code>-Wl,-no_exported_symbols</code> in <code>opt</code> for Mach-O; <a href="./../features/debugging#strip">strip</a>);</li><li>library <code>defines</code> passed to C++20 module compiles and <code>clang-scan-deps</code> scans on macOS as on Linux and Windows.</li></ul><h2 id="static-by-default" tabindex="-1">Static by Default <a class="header-anchor" href="#static-by-default" aria-label="Permalink to &quot;Static by Default&quot;">​</a></h2><p>By default, <code>rules_cc</code> links <code>cc_library</code> dependencies of <code>cc_test</code> targets as separate shared libraries when <code>supports_dynamic_linker</code> is enabled. Because every shared library linked by xclang carries its own private static <code>libc++</code> (<a href="./hermeticity#one-libc-per-shared-object">one <code>libc++</code> per shared object</a>), linking each <code>cc_library</code> as a shared object gave each library a separate <code>libc++</code> instance (causing <code>kotatsu</code>&#39;s tests to crash at startup with a double free, and failing to link on Windows).</p><p>The toolchain config therefore disables <code>supports_dynamic_linker</code> by default so <code>cc_library</code> targets link statically into executables and tests. <code>cc_binary(linkshared = True)</code> still produces shared libraries (<code>libfoo.so</code>, <code>libfoo.dylib</code>, <code>foo.dll</code>), and <code>features = [&quot;supports_dynamic_linker&quot;]</code> re-enables dynamic linking for Linux targets.</p><h2 id="vendor-sdks-as-repositories" tabindex="-1">Vendor SDKs as Repositories <a class="header-anchor" href="#vendor-sdks-as-repositories" aria-label="Permalink to &quot;Vendor SDKs as Repositories&quot;">​</a></h2><p>The MSVC targets require Microsoft&#39;s CRT, STL and Windows SDK, and the macOS targets on Linux and Windows hosts require Apple&#39;s macOS SDK. Whereas plain <code>clang</code> and CMake unpack fetched SDKs into <code>&lt;toolchain&gt;/sdk/</code> with the <a href="./../reference/xclang-command"><code>xclang</code> command</a>, a Bazel build cannot write into the toolchain repository and must declare every SDK file as an input. <code>bazel/sdk.bzl</code> manages each vendor SDK as its own external repository:</p><ul><li><strong>License acceptance in the root <code>MODULE.bazel</code></strong>: only <code>xclang.windows_sdk</code> and <code>xclang.macos_sdk</code> tags in the root module (<code>mod.is_root</code>) take effect, so a dependency module cannot accept a vendor license on behalf of its consumers.</li><li><strong>Bazel downloads, <code>xclang</code> unpacks</strong>: the repository rule runs <code>xclang sdk packages &lt;vendor&gt; --json</code> to query the pinned package URLs, sizes and <code>sha256</code> digests, downloads them with <code>rctx.download</code> into Bazel&#39;s shared repository cache (applying any configured Bazel mirror, proxy or <code>--distdir</code>), and invokes <code>xclang sdk fetch &lt;vendor&gt; --accept-license --cache downloads --sdk-dir sdk</code> to unpack the archive and create case-folding links on case-sensitive file systems. When Apple withdraws a pinned macOS Command Line Tools package, <code>xclang sdk fetch</code> locates the replacement package in Apple&#39;s catalogs and verifies the unpacked SDK by its content digest (<a href="./macos#packages-apple-withdraws-and-content-digests">packages Apple withdraws</a>).</li><li><strong>Generated <code>sdk.cfg</code></strong>: each SDK repository writes <code>sdk.cfg</code> with paths relative to the execution root (<code>-isysroot external/&lt;repo&gt;/sdk/&lt;name&gt;</code> for macOS, and the rewritten <code>&lt;arch&gt;-pc-windows-msvc.cfg</code> naming the MSVC and Windows SDK version directories for MSVC targets), which the toolchain&#39;s <code>cfg/&lt;target&gt;.cfg</code> includes via <code>@../../&lt;sdk_repo&gt;/sdk.cfg</code>.</li><li><strong>Lazy per-architecture repositories</strong>: <code>xclang_windows_sdk_x86_64</code> (310 MB download), <code>xclang_windows_sdk_aarch64</code> (380 MB download) and <code>xclang_macos_sdk</code> are fetched only when a build targets that platform.</li><li><strong>Split compile and link filegroups</strong>: <code>BUILD.bazel</code> in the SDK repository exports <code>:compiler_files</code> and <code>:linker_files</code> via <code>glob()</code>. For the macOS SDK, <code>_unlink_cycles</code> removes directory symlink cycles (such as <code>Ruby.framework</code>&#39;s <code>Headers/ruby/ruby -&gt; .</code>) before <code>glob()</code> runs; <code>:compiler_files</code> stages the headers and frameworks (15,000 files) and <code>:linker_files</code> stages the <code>.tbd</code> stubs and <code>SDKSettings.*</code> (9,800 files). For an MSVC target, <code>:compiler_files</code> declares 7,300 headers and links and <code>:linker_files</code> declares 1,300 libraries.</li></ul><h2 id="the-registry" tabindex="-1">The Registry <a class="header-anchor" href="#the-registry" aria-label="Permalink to &quot;The Registry&quot;">​</a></h2><p>After <code>published.yml</code> builds and tests a release tag against the published release assets, <code>node packages/bazel/bazel.ts archive</code> builds <code>xclang-bazel-&lt;version&gt;.tar.gz</code> and publishes the module to <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>. <code>bazel.ts</code> constructs the <code>ustar</code> archive deterministically in memory—sorted entries, <code>0755</code>/<code>0644</code> permissions, zeroed owner and timestamp fields, and gzip&#39;s OS header byte set to <code>255</code>—so the registry archive is identical byte for byte on every host.</p>',29)])])}const g=o(t,[["render",i]]);export{u as __pageData,g as default};
